#!/usr/bin/env node
/**
 * The inspection list, the same in the hub portal and the hub app (migration 129).
 *  - The server builds each item's list: its part, OEM number, position, each spec, and "Condition: no damage, sealed box". The portal and the
 *    app show exactly these lines; each tick and each received quantity is saved as it is made, so work started on one can be finished on the other.
 *  - "Confirm Inspected" stays off until every line is ticked and every item's received quantity is entered. A quantity different from the order
 *    must be flagged; it goes on only after Leap reviewed the flag and chose to continue. The server refuses the step otherwise (code
 *    inspection_incomplete or quantity_mismatch), so no screen can skip it.
 *  - Chinese and English.
 *
 *   node scripts/patch-inspection-list.js            dry run
 *   node scripts/patch-inspection-list.js --write    applies it (each changed file is saved as <file>.before-inspection-list first)
 * Then: cd services\api ; npm run migrate ; restart the API. Hub portal: Ctrl+F5. Hub app: q, then flutter run with your API address.
 *
 * A file that is not as this patch expects is NOT changed (the whole patch stops). Windows (CRLF) line endings are handled. Running it twice is harmless.
 */
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const write = process.argv.includes('--write');
const DATA = {"created":[{"file":"services/api/db/migrations/129_inspection_checks.sql","what":"database: the inspection list's ticks (migration 129)","text":"-- Migration 129: the inspection list's ticks, kept per order line (the keys of the lines the hub confirmed against the real part), so the hub\n-- portal and the hub app show the same list with the same ticks, and the \"Confirm Inspected\" step can be refused until every line is ticked and\n-- every item's received quantity is entered (see src/modules/inspection/service.js).\nALTER TABLE order_line_items ADD COLUMN IF NOT EXISTS inspection_checks JSONB NOT NULL DEFAULT '[]'::jsonb;\n"},{"file":"services/api/src/modules/inspection/service.js","what":"server: the inspection list, and what stops \"Confirm Inspected\"","text":"/**\n * The inspection list (migration 129): ONE list for each item, built here, so the hub portal and the hub app always show the same lines:\n *   the part, its OEM number, its position (when it has one and no \"Position\" spec), each of its specs, and a fixed line for its condition.\n * The hub ticks each line against the real part; the ticks are saved on the order line, so work started on the app can be finished on the portal.\n *\n * \"Confirm Inspected\" (the 'inspected' step) is refused until, for every item:\n *   - every line of its list is ticked, and\n *   - its received quantity is entered, and\n *   - the received quantity equals the ordered quantity. A different quantity must be FLAGGED; it may go on only after Leap reviewed the flag and\n *     chose \"continue processing\" (the shipment then comes back to this step with that resolution).\n */\nconst CONDITION = { key: 'condition', en: 'Condition: no damage, sealed box', zh: '外观：无损坏，包装完好' };\nconst clean = (v) => (v === null || v === undefined ? '' : String(v).trim());\n\nclass InspectionError extends Error {\n  constructor(message, status = 400, code = undefined) { super(message); this.status = status; this.code = code; }\n}\n\n/** The list for one item: [{ key, en, zh }]. `item`: { part, oemNumber, position, attributes: [{ name, value }] }. */\nfunction checklistFor(item) {\n  const list = [];\n  const part = clean(item.part); const oem = clean(item.oemNumber); const position = clean(item.position);\n  const attributes = (item.attributes || []).filter((a) => clean(a.name) && clean(a.value));\n  if (part) list.push({ key: 'part', en: `Part: ${part}`, zh: `配件：${part}` });\n  if (oem) list.push({ key: 'oem', en: `OEM: ${oem}`, zh: `OEM：${oem}` });\n  if (position && !attributes.some((a) => clean(a.name).toLowerCase() === 'position')) list.push({ key: 'position', en: `Position: ${position}`, zh: `位置：${position}` });\n  for (const a of attributes) list.push({ key: `attr:${clean(a.name)}`, en: `${clean(a.name)}: ${clean(a.value)}`, zh: `${clean(a.name)}：${clean(a.value)}` });\n  list.push({ ...CONDITION });\n  return list;\n}\n\nconst checkedOf = (raw) => (Array.isArray(raw) ? raw.filter((k) => typeof k === 'string') : []);\n\n/** The items of a sub-order, each with its list and the ticks saved for it. */\nasync function itemsOf(db, subOrderId) {\n  const { rows } = await db.query(\n    `SELECT oli.product_id, oli.quantity, oli.received_quantity, oli.inspection_checks, p.name, p.part, p.position, p.oem_number\n     FROM order_line_items oli JOIN products p ON p.id = oli.product_id WHERE oli.sub_order_id = $1 ORDER BY oli.product_id`, [subOrderId]\n  );\n  const out = [];\n  for (const r of rows) {\n    const { rows: attrs } = await db.query('SELECT attribute_name, attribute_value FROM product_attributes WHERE product_id = $1 ORDER BY attribute_name', [r.product_id]);\n    const item = { part: r.part, oemNumber: r.oem_number, position: r.position, attributes: attrs.map((a) => ({ name: a.attribute_name, value: a.attribute_value })) };\n    const checklist = checklistFor(item);\n    const keys = new Set(checklist.map((c) => c.key));\n    out.push({ productId: r.product_id, name: r.name, quantity: r.quantity, receivedQuantity: r.received_quantity, checklist, checkedKeys: checkedOf(r.inspection_checks).filter((k) => keys.has(k)) });\n  }\n  return out;\n}\n\n/** What is still missing for each item: [{ productId, name, missingChecks, missingQuantity, mismatch: { ordered, received } | null }]. */\nfunction gapsOf(items) {\n  return items.map((i) => ({\n    productId: i.productId, name: i.name,\n    missingChecks: i.checklist.filter((c) => !i.checkedKeys.includes(c.key)).length,\n    missingQuantity: i.receivedQuantity === null || i.receivedQuantity === undefined,\n    mismatch: i.receivedQuantity !== null && i.receivedQuantity !== undefined && i.receivedQuantity !== i.quantity ? { ordered: i.quantity, received: i.receivedQuantity } : null,\n  })).filter((g) => g.missingChecks > 0 || g.missingQuantity || g.mismatch);\n}\n\n/** May this shipment be marked inspected? { allowed } or { allowed: false, code, error, gaps }. `shipment`: the hub_shipments row. */\nasync function inspectCheck(db, shipment) {\n  const gaps = gapsOf(await itemsOf(db, shipment.sub_order_id));\n  const incomplete = gaps.filter((g) => g.missingChecks > 0 || g.missingQuantity);\n  if (incomplete.length) {\n    return { allowed: false, code: 'inspection_incomplete', gaps, error: `Finish the inspection list first: ${incomplete.map((g) => [g.missingChecks ? `${g.name}: ${g.missingChecks} check${g.missingChecks === 1 ? '' : 's'}` : null, g.missingQuantity ? `${g.name}: quantity received` : null].filter(Boolean).join(', ')).join('; ')}.` };\n  }\n  const mismatched = gaps.filter((g) => g.mismatch);\n  if (mismatched.length && shipment.resolution !== 'continue_processing') {\n    return { allowed: false, code: 'quantity_mismatch', gaps, error: `The quantity received does not match the order (${mismatched.map((g) => `${g.name}: ${g.mismatch.received} of ${g.mismatch.ordered}`).join('; ')}). Flag this shipment so Leap can decide.` };\n  }\n  return { allowed: true };\n}\n\n/** The hub ticks (or unticks) lines of one item's list. Only while the shipment is opened (being inspected). Unknown keys are dropped. */\nasync function saveChecks(db, { shipmentId, hubId, productId, checked }) {\n  if (!Array.isArray(checked) || checked.some((k) => typeof k !== 'string')) throw new InspectionError('checked must be a list of the ticked lines (their keys)');\n  const { rows } = await db.query('SELECT id, status, sub_order_id FROM hub_shipments WHERE id = $1 AND hub_id = $2', [shipmentId, hubId]);\n  if (rows.length === 0) throw new InspectionError('Shipment not found', 404);\n  if (rows[0].status !== 'opened') throw new InspectionError('The inspection list can be ticked only while the shipment is being inspected (opened).', 409, 'not_inspecting');\n  const item = (await itemsOf(db, rows[0].sub_order_id)).find((i) => i.productId === productId);\n  if (!item) throw new InspectionError('This item is not in the shipment', 404);\n  const keys = new Set(item.checklist.map((c) => c.key));\n  const kept = [...new Set(checked)].filter((k) => keys.has(k));\n  await db.query('UPDATE order_line_items SET inspection_checks = $1::jsonb WHERE sub_order_id = $2 AND product_id = $3', [JSON.stringify(kept), rows[0].sub_order_id, productId]);\n  return { productId, checkedKeys: kept };\n}\n\n/** For the hub's shipment view: an order line (with inspection_checks) and its product_attributes rows -> { checklist, checkedKeys }. */\nfunction inspectionFields(row, attrRows) {\n  const checklist = checklistFor({ part: row.part, oemNumber: row.oem_number, position: row.position, attributes: (attrRows || []).map((a) => ({ name: a.attribute_name, value: a.attribute_value })) });\n  const keys = new Set(checklist.map((c) => c.key));\n  return { checklist, checkedKeys: checkedOf(row.inspection_checks).filter((k) => keys.has(k)) };\n}\n\nmodule.exports = { CONDITION, inspectionFields, InspectionError, checklistFor, itemsOf, gapsOf, inspectCheck, saveChecks };\n"},{"file":"services/api/test/inspection.test.js","what":"server: tests","text":"const test = require('node:test');\nconst assert = require('node:assert/strict');\nconst { checklistFor, gapsOf } = require('../src/modules/inspection/service');\n\n// The inspection list (migration 129): the same lines for the hub portal and the hub app, and what stops \"Confirm Inspected\".\ntest('the list: part, OEM, position, each spec, and the condition line', () => {\n  const list = checklistFor({ part: 'Brake pads', oemNumber: '04465-33471', position: 'Front', attributes: [{ name: 'Material', value: 'Ceramic' }] });\n  assert.deepEqual(list.map((c) => c.key), ['part', 'oem', 'position', 'attr:Material', 'condition']);\n  assert.equal(list[0].en, 'Part: Brake pads'); assert.equal(list[0].zh, '配件：Brake pads');\n  // a \"Position\" spec is not shown twice; empty values are left out\n  const two = checklistFor({ part: '', oemNumber: null, position: 'Front', attributes: [{ name: 'Position', value: 'Front left' }, { name: 'Colour', value: '' }] });\n  assert.deepEqual(two.map((c) => c.key), ['attr:Position', 'condition']);\n});\n\ntest('what is still missing: ticks, the received quantity, a different quantity', () => {\n  const list = checklistFor({ part: 'Oil filter', attributes: [] });\n  const item = (over) => ({ productId: 'p1', name: 'Oil filter', quantity: 2, receivedQuantity: 2, checklist: list, checkedKeys: ['part', 'condition'], ...over });\n  assert.deepEqual(gapsOf([item()]), []);\n  assert.equal(gapsOf([item({ checkedKeys: ['part'] })])[0].missingChecks, 1);\n  assert.equal(gapsOf([item({ receivedQuantity: null })])[0].missingQuantity, true);\n  assert.deepEqual(gapsOf([item({ receivedQuantity: 1 })])[0].mismatch, { ordered: 2, received: 1 });\n});\n"},{"file":"apps/hub-portal/src/InspectionList.jsx","what":"hub portal: the inspection list","text":"import React, { useEffect, useRef, useState } from \"react\";\nimport { API_BASE_URL, SessionExpiredError } from \"./auth\";\nimport { useLang } from \"./langContext\";\n\n// The inspection list (migration 129), while a shipment is being inspected (opened). The server builds the list, so the hub app shows exactly\n// the same lines (lib/features/shipment/shipment_detail_screen.dart). Each tick and each received quantity is saved as it is made, so work started\n// on the app can be finished here. \"Confirm Inspected\" stays off until every line is ticked and every item's received quantity is entered and\n// equal to the order (a different quantity is flagged; Leap decides) -- the server refuses it too.\nconst C = { ink: \"#14171C\", line: \"#E4E6EA\", card: \"#FFFFFF\", muted: \"#6B7280\", torque: \"#2A5FD9\", gauge: \"#1E9D6B\", gaugeBg: \"#E4F5EC\", red: \"#C0362C\", redBg: \"#FBE7E5\" };\nconst body = { fontFamily: \"'Inter', sans-serif\" };\n\nexport const INSPECTION_TEXT = {\n  zh: {\n    title: \"质检清单\", checkAll: \"全部勾选\", enterQuantity: \"请填写实收数量\", stillNeeded: \"确认已质检前还需完成：\", allDone: \"清单与实收数量已全部确认\",\n    ordered: \"订购\", received: \"实收\", mismatchHint: \"实收数量与订单不符：请标记此包裹，由 Leap 决定。\", saveFailed: \"未能保存，请重试。\",\n    checksDone: (d, t) => `已确认 ${d} / ${t} 项`,\n    needChecks: (name, n) => `${name}：还有 ${n} 项未勾选`, needQuantity: (name) => `${name}：实收数量`, needFlag: (name, r, o) => `${name}：实收 ${r} / 订购 ${o}，请标记此包裹`,\n  },\n  en: {\n    title: \"Inspection list\", checkAll: \"Check all\", enterQuantity: \"Enter the quantity received\", stillNeeded: 'Still needed before \"Confirm Inspected\":',\n    allDone: \"List and quantities all confirmed\", ordered: \"Ordered\", received: \"Received\",\n    mismatchHint: \"The quantity received does not match the order: flag this shipment so Leap can decide.\", saveFailed: \"Could not save. Try again.\",\n    checksDone: (d, t) => `${d} of ${t} checks confirmed`,\n    needChecks: (name, n) => `${name}: ${n} ${n === 1 ? \"check\" : \"checks\"}`, needQuantity: (name) => `${name}: quantity received`, needFlag: (name, r, o) => `${name}: received ${r} of ${o}, flag this shipment`,\n  },\n};\n\nasync function send(token, path, method, payload) {\n  const response = await fetch(`${API_BASE_URL}${path}`, { method, headers: { \"Content-Type\": \"application/json\", Authorization: `Bearer ${token}` }, body: JSON.stringify(payload) });\n  if (response.status === 401) throw new SessionExpiredError(\"Your session has expired. Please log in again.\");\n  const data = await response.json().catch(() => ({}));\n  if (!response.ok) throw new Error(data.error || `Request failed (${response.status})`);\n  return data;\n}\n\nconst asCount = (text) => (/^\\s*\\d+\\s*$/.test(String(text)) ? Number(text) : null);\n\n/** What still stops \"Confirm Inspected\" (one line each); empty when it may go on. */\nexport function inspectionMissing(shipment, checks, quantities, x) {\n  const out = [];\n  for (const item of shipment.items) {\n    const checked = checks[item.productId] || [];\n    const left = (item.checklist || []).filter((c) => !checked.includes(c.key)).length;\n    if (left > 0) out.push(x.needChecks(item.name, left));\n    const received = asCount(quantities[item.productId] ?? \"\");\n    if (received === null) out.push(x.needQuantity(item.name));\n    else if (received !== item.quantity && shipment.resolution !== \"continue_processing\") out.push(x.needFlag(item.name, received, item.quantity));\n  }\n  return out;\n}\n\n/** The box under the step's button: what is still missing, or that everything is confirmed. */\nexport function InspectionMissing({ state }) {\n  const { lang } = useLang();\n  const x = INSPECTION_TEXT[lang] || INSPECTION_TEXT.en;\n  if (state.missing.length === 0) {\n    return <div style={{ ...body, marginTop: 16, background: C.gaugeBg, color: C.gauge, borderRadius: 10, padding: \"10px 12px\", fontSize: 12.5, fontWeight: 700 }}>✓ {x.allDone}</div>;\n  }\n  return (\n    <div data-testid=\"inspection-missing\" style={{ ...body, marginTop: 16, background: C.redBg, color: C.red, borderRadius: 10, padding: \"10px 12px\", fontSize: 12.5 }}>\n      <div style={{ fontWeight: 700, marginBottom: 4 }}>{x.stillNeeded}</div>\n      {state.missing.map((line) => <div key={line}>• {line}</div>)}\n    </div>\n  );\n}\n\nexport default function InspectionList({ shipmentId, shipment, token, onChange, onSessionExpired }) {\n  const { lang } = useLang();\n  const x = INSPECTION_TEXT[lang] || INSPECTION_TEXT.en;\n  const [checks, setChecks] = useState(() => Object.fromEntries(shipment.items.map((i) => [i.productId, i.checkedKeys || []])));\n  const [quantities, setQuantities] = useState(() => Object.fromEntries(shipment.items.map((i) => [i.productId, i.receivedQuantity === null || i.receivedQuantity === undefined ? \"\" : String(i.receivedQuantity)])));\n  const [pending, setPending] = useState(0);      // saves on their way: the step waits for them\n  const [error, setError] = useState(null);\n  const latestQuantity = useRef({});\n\n  const missing = inspectionMissing(shipment, checks, quantities, x);\n  const ready = missing.length === 0 && pending === 0;\n  useEffect(() => { onChange({ ready, missing }); }, [ready, missing.join(\"|\")]); // eslint-disable-line react-hooks/exhaustive-deps\n\n  const failed = (err) => {\n    if (err instanceof SessionExpiredError) return onSessionExpired && onSessionExpired();\n    setError(err.message || x.saveFailed);\n  };\n  const run = async (job) => {\n    setPending((n) => n + 1); setError(null);\n    try { await job(); } catch (err) { failed(err); return false; } finally { setPending((n) => n - 1); }\n    return true;\n  };\n\n  const setItemChecks = async (productId, next) => {\n    const before = checks[productId] || [];\n    setChecks((c) => ({ ...c, [productId]: next }));\n    const ok = await run(() => send(token, `/hub/me/shipments/${encodeURIComponent(shipmentId)}/items/${encodeURIComponent(productId)}/checks`, \"PUT\", { checked: next }));\n    if (!ok) setChecks((c) => ({ ...c, [productId]: before }));      // not saved: the tick goes back\n  };\n\n  const setQuantity = (productId, text) => {\n    setQuantities((q) => ({ ...q, [productId]: text }));\n    const n = asCount(text);\n    if (n === null) return;\n    latestQuantity.current[productId] = n;\n    run(async () => {\n      if (latestQuantity.current[productId] !== n) return;      // a newer number was typed: that one is saved instead\n      await send(token, `/hub/me/shipments/${encodeURIComponent(shipmentId)}/items/${encodeURIComponent(productId)}/received`, \"PATCH\", { receivedQuantity: n });\n    });\n  };\n\n  return (\n    <div data-testid=\"inspection-list\" style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 10, padding: 14 }}>\n      <div style={{ ...body, fontSize: 11.5, fontWeight: 700, color: C.muted, letterSpacing: \"0.04em\", marginBottom: 4 }}>{x.title.toUpperCase()}</div>\n      {shipment.items.map((item, index) => {\n        const list = item.checklist || [];\n        const checked = checks[item.productId] || [];\n        const done = list.filter((c) => checked.includes(c.key)).length;\n        const typed = quantities[item.productId] ?? \"\";\n        const received = asCount(typed);\n        const mismatch = received !== null && received !== item.quantity;\n        const empty = received === null;\n        const boxColor = empty || mismatch ? C.red : C.gauge;\n        return (\n          <div key={item.productId} style={{ borderTop: index ? `1px solid ${C.line}` : \"none\", padding: \"12px 0 4px\" }}>\n            <div style={{ ...body, fontSize: 14, fontWeight: 700, color: C.ink, marginBottom: 6 }}>{item.name} × {item.quantity}</div>\n            {list.map((c) => {\n              const on = checked.includes(c.key);\n              return (\n                <label key={c.key} style={{ ...body, display: \"flex\", alignItems: \"center\", gap: 8, padding: \"3px 0\", fontSize: 12.5, color: on ? C.ink : C.muted, cursor: \"pointer\" }}>\n                  <input type=\"checkbox\" checked={on} aria-label={c[lang] || c.en}\n                    onChange={() => setItemChecks(item.productId, on ? checked.filter((k) => k !== c.key) : [...checked, c.key])}\n                    style={{ width: 16, height: 16, accentColor: C.gauge, margin: 0, cursor: \"pointer\" }} />\n                  {c[lang] || c.en}\n                </label>\n              );\n            })}\n            <div style={{ ...body, display: \"flex\", justifyContent: \"space-between\", alignItems: \"center\", fontSize: 11, color: C.muted, margin: \"6px 0 10px\" }}>\n              <span>{x.checksDone(done, list.length)}</span>\n              {done < list.length && (\n                <button type=\"button\" onClick={() => setItemChecks(item.productId, list.map((c) => c.key))}\n                  style={{ ...body, border: \"none\", background: \"none\", padding: 0, color: C.torque, fontWeight: 700, fontSize: 11.5, cursor: \"pointer\" }}>{x.checkAll}</button>\n              )}\n            </div>\n            <div style={{ ...body, display: \"flex\", alignItems: \"center\", gap: 10, fontSize: 12.5, color: C.muted }}>\n              <span>{x.ordered}: {item.quantity}</span>\n              <span>{x.received}</span>\n              <input inputMode=\"numeric\" aria-label={`${x.received}: ${item.name}`} value={typed} onChange={(e) => setQuantity(item.productId, e.target.value)}\n                style={{ ...body, width: 64, height: 34, boxSizing: \"border-box\", borderRadius: 8, border: `1.5px solid ${boxColor}`, background: empty ? C.redBg : \"#fff\", textAlign: \"center\", fontSize: 14, fontWeight: 700, color: mismatch ? C.red : C.ink }} />\n            </div>\n            {empty && <div style={{ ...body, fontSize: 11.5, fontWeight: 600, color: C.red, marginTop: 6 }}>{x.enterQuantity}</div>}\n            {!empty && mismatch && shipment.resolution !== \"continue_processing\" && <div style={{ ...body, fontSize: 11.5, fontWeight: 600, color: C.red, marginTop: 6 }}>{x.mismatchHint}</div>}\n          </div>\n        );\n      })}\n      {error && <div style={{ ...body, fontSize: 12, color: C.red, background: C.redBg, borderRadius: 8, padding: 8, marginTop: 8 }}>{error}</div>}\n    </div>\n  );\n}\n"},{"file":"apps/hub-mobile/lib/features/shipment/inspection_text.dart","what":"hub app: the inspection list's words","text":"/// The inspection list's words (migration 129), in Chinese and English: the same as the hub portal's src/InspectionList.jsx.\nlibrary;\n\nclass InspectionText {\n  final String title, checkAll, enterQuantity, stillNeeded, allDone, ordered, received, mismatchHint, saveFailed;\n  final String Function(int done, int total) checksDone;\n  final String Function(String name, int n) needChecks;\n  final String Function(String name) needQuantity;\n  final String Function(String name, int received, int ordered) needFlag;\n  const InspectionText({\n    required this.title, required this.checkAll, required this.enterQuantity, required this.stillNeeded, required this.allDone,\n    required this.ordered, required this.received, required this.mismatchHint, required this.saveFailed,\n    required this.checksDone, required this.needChecks, required this.needQuantity, required this.needFlag,\n  });\n}\n\nfinal Map<String, InspectionText> kInspectionText = {\n  'zh': InspectionText(\n    title: '质检清单', checkAll: '全部勾选', enterQuantity: '请填写实收数量', stillNeeded: '确认已质检前还需完成：', allDone: '清单与实收数量已全部确认',\n    ordered: '订购', received: '实收', mismatchHint: '实收数量与订单不符：请标记此包裹，由 Leap 决定。', saveFailed: '未能保存，请重试。',\n    checksDone: (d, t) => '已确认 $d / $t 项',\n    needChecks: (name, n) => '$name：还有 $n 项未勾选',\n    needQuantity: (name) => '$name：实收数量',\n    needFlag: (name, r, o) => '$name：实收 $r / 订购 $o，请标记此包裹',\n  ),\n  'en': InspectionText(\n    title: 'Inspection list', checkAll: 'Check all', enterQuantity: 'Enter the quantity received', stillNeeded: 'Still needed before \"Confirm Inspected\":',\n    allDone: 'List and quantities all confirmed', ordered: 'Ordered', received: 'Received',\n    mismatchHint: 'The quantity received does not match the order: flag this shipment so Leap can decide.', saveFailed: 'Could not save. Try again.',\n    checksDone: (d, t) => '$d of $t checks confirmed',\n    needChecks: (name, n) => '$name: $n ${n == 1 ? 'check' : 'checks'}',\n    needQuantity: (name) => '$name: quantity received',\n    needFlag: (name, r, o) => '$name: received $r of $o, flag this shipment',\n  ),\n};\n"}],"anchored":[{"file":"services/api/src/modules/hub/routes.js","what":"server: the list in each shipment, saving ticks, and the \"Confirm Inspected\" rule","done":"require('../inspection/service')","pairs":[["const parcelCosts = require('../parcelCosts/service');","const inspection = require('../inspection/service');      // the inspection list (migration 129)\nconst parcelCosts = require('../parcelCosts/service');"],["SELECT oli.product_id, oli.quantity, oli.received_quantity, p.name, p.part, p.position, p.oem_number","SELECT oli.product_id, oli.quantity, oli.received_quantity, oli.inspection_checks, p.name, p.part, p.position, p.oem_number"],["        attributes: attrRows.map((a) => ({ name: a.attribute_name, value: a.attribute_value })),\n      };\n","        attributes: attrRows.map((a) => ({ name: a.attribute_name, value: a.attribute_value })),\n        // the inspection list (migration 129): the same lines on the hub portal and the hub app, and the ones already ticked\n        ...inspection.inspectionFields(i, attrRows),\n      };\n"],["// POST /hub/me/shipments/:id/events  { step, notes?, photos: [url,...], trackingNumber? }\n","// PUT /hub/me/shipments/:id/items/:productId/checks  { checked: [key, ...] } -- the inspection list's ticks for one item (migration 129), while\n// the shipment is being inspected (opened). Answers { productId, checkedKeys }.\nrouter.put('/me/shipments/:id/items/:productId/checks', requireAuth, requireRole('hub_staff'), async (req, res, next) => {\n  try {\n    res.json(await inspection.saveChecks(db, { shipmentId: req.params.id, hubId: req.user.hubId, productId: req.params.productId, checked: (req.body || {}).checked }));\n  } catch (err) {\n    if (err instanceof inspection.InspectionError) return res.status(err.status).json({ error: err.message, code: err.code });\n    next(err);\n  }\n});\n\n// POST /hub/me/shipments/:id/events  { step, notes?, photos: [url,...], trackingNumber? }\n"],["    let returnNotifications = [];\n    if (step === 'flagged') {\n","    // The inspection list (migration 129): every line ticked and every item's received quantity entered, and equal to the order -- a different\n    // quantity is flagged, and goes on only after Leap reviewed the flag and chose to continue.\n    if (step === 'inspected') {\n      const ok = await inspection.inspectCheck(client, shipment);\n      if (!ok.allowed) {\n        await client.query('ROLLBACK');\n        return res.status(409).json({ error: ok.error, code: ok.code, gaps: ok.gaps });\n      }\n    }\n\n    let returnNotifications = [];\n    if (step === 'flagged') {\n"]]},{"file":"apps/hub-portal/src/App.jsx","what":"hub portal: the inspection list while inspecting; \"Confirm Inspected\" waits for it","done":"from \"./InspectionList\"","pairs":[["import ShippingCostCard from \"./ShippingCostCard\";","import InspectionList, { InspectionMissing } from \"./InspectionList\";      // the inspection list while inspecting (migration 129)\nimport ShippingCostCard from \"./ShippingCostCard\";"],["  const [mayShip, setMayShip] = useState(false);","  const [inspection, setInspection] = useState({ ready: false, missing: [] });      // the inspection list: may \"Confirm Inspected\" go on, and what is missing\n  const [mayShip, setMayShip] = useState(false);"],["        <div style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 10, padding: 14 }}>\n          <div style={{ ...body, fontSize: 11.5, fontWeight: 700, color: C.muted, marginBottom: 8 }}>{t.detail.items.toUpperCase()}</div>\n          {shipment.items.map((item, i) => (\n            <div key={i} style={{ ...body, fontSize: 13, color: C.ink, padding: \"4px 0\" }}>{item.name} × {item.quantity}</div>\n          ))}\n        </div>\n","        {shipment.status === \"opened\" && !showFlagForm ? (\n          <InspectionList key={shipment.status} shipmentId={shipmentId} shipment={shipment} token={getStoredToken()} onChange={setInspection} onSessionExpired={onSessionExpired} />\n        ) : (\n        <div style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 10, padding: 14 }}>\n          <div style={{ ...body, fontSize: 11.5, fontWeight: 700, color: C.muted, marginBottom: 8 }}>{t.detail.items.toUpperCase()}</div>\n          {shipment.items.map((item, i) => (\n            <div key={i} style={{ ...body, fontSize: 13, color: C.ink, padding: \"4px 0\" }}>{item.name} × {item.quantity}</div>\n          ))}\n        </div>\n        )}\n"],["            <button\n              onClick={() => submitStep(info.next)}\n","            {info.next === \"inspected\" && <InspectionMissing state={inspection} />}\n\n            <button\n              onClick={() => submitStep(info.next)}\n"],["              disabled={isSubmitting || (info.next === \"shipped_to_buyer\" && !mayShip)}","              disabled={isSubmitting || (info.next === \"shipped_to_buyer\" && !mayShip) || (info.next === \"inspected\" && !inspection.ready)}"],["background: isSubmitting || (info.next === \"shipped_to_buyer\" && !mayShip) ? \"#D1D5DB\" : C.signal","background: isSubmitting || (info.next === \"shipped_to_buyer\" && !mayShip) || (info.next === \"inspected\" && !inspection.ready) ? \"#D1D5DB\" : C.signal"]]},{"file":"apps/hub-mobile/lib/models/shipment.dart","what":"hub app: the list in each item","done":"class InspectionCheck","pairs":[["  final List<ProductAttribute> attributes;\n\n  ShipmentItem({\n    required this.productId, required this.name, required this.quantity,\n    this.receivedQuantity, this.part, this.position, this.oemNumber,\n    this.attributes = const [],\n  });","  final List<ProductAttribute> attributes;\n  // The inspection list (migration 129): built by the server, the same on the hub portal; and the lines already ticked.\n  final List<InspectionCheck> checklist;\n  final List<String> checkedKeys;\n\n  ShipmentItem({\n    required this.productId, required this.name, required this.quantity,\n    this.receivedQuantity, this.part, this.position, this.oemNumber,\n    this.attributes = const [], this.checklist = const [], this.checkedKeys = const [],\n  });"],["            .map((a) => ProductAttribute.fromJson(a as Map<String, dynamic>))\n            .toList(),\n      );","            .map((a) => ProductAttribute.fromJson(a as Map<String, dynamic>))\n            .toList(),\n        checklist: (json['checklist'] as List<dynamic>? ?? [])\n            .map((c) => InspectionCheck.fromJson(c as Map<String, dynamic>))\n            .toList(),\n        checkedKeys: (json['checkedKeys'] as List<dynamic>? ?? []).map((k) => k as String).toList(),\n      );"],["      ProductAttribute(name: json['name'] as String, value: json['value'] as String);\n}\n","      ProductAttribute(name: json['name'] as String, value: json['value'] as String);\n}\n\n/// One line of the inspection list (migration 129): its key (what is saved when it is ticked) and its words in English and Chinese.\nclass InspectionCheck {\n  final String key;\n  final String en;\n  final String zh;\n\n  InspectionCheck({required this.key, required this.en, required this.zh});\n\n  String label(String language) => language == 'zh' ? zh : en;\n\n  factory InspectionCheck.fromJson(Map<String, dynamic> json) =>\n      InspectionCheck(key: json['key'] as String, en: json['en'] as String, zh: (json['zh'] ?? json['en']) as String);\n}\n"]]},{"file":"apps/hub-mobile/lib/services/api_client.dart","what":"hub app: saving ticks","done":"saveInspectionChecks","pairs":[["  Future<void> recordReceivedQuantity(String token, String shipmentId, String productId, int receivedQuantity) async {\n    await _authedMutate('PATCH', '/hub/me/shipments/$shipmentId/items/$productId/received', token, {\n      'receivedQuantity': receivedQuantity,\n    });\n  }\n","  Future<void> recordReceivedQuantity(String token, String shipmentId, String productId, int receivedQuantity) async {\n    await _authedMutate('PATCH', '/hub/me/shipments/$shipmentId/items/$productId/received', token, {\n      'receivedQuantity': receivedQuantity,\n    });\n  }\n\n  /// The inspection list's ticks for one item (migration 129): the keys of the lines confirmed against the real part.\n  Future<void> saveInspectionChecks(String token, String shipmentId, String productId, List<String> checked) async {\n    await _authedMutate('PUT', '/hub/me/shipments/$shipmentId/items/$productId/checks', token, {'checked': checked});\n  }\n"]]},{"file":"apps/hub-mobile/lib/features/shipment/shipment_detail_screen.dart","what":"hub app: the same list; \"Confirm Inspected\" waits for it","done":"import 'inspection_text.dart';","pairs":[["import 'shipping_cost_card.dart';","import 'shipping_cost_card.dart';\nimport 'inspection_text.dart';      // the inspection list's words (migration 129)"],["  final Map<String, Set<String>> _checkedSpecs = {};\n","  final Map<String, Set<String>> _checkedSpecs = {};\n  // what still stops \"Confirm Inspected\" (worked out on each build; the server checks the same)\n  List<String> _inspectionMissingNow = const [];\n"],["    final allChecksConfirmed = nextStatus != 'inspected' ||\n        shipment.items.every((item) => (_checkedSpecs[item.productId]?.length ?? 0) >= _specLabelsFor(item).length);\n","    // The inspection list (migration 129): every line ticked and every item's received quantity entered, and equal to the order (a different\n    // quantity is flagged; it goes on only after Leap chose to continue). The same as the hub portal; the server refuses it otherwise.\n    _inspectionMissingNow = nextStatus == 'inspected' ? _inspectionMissing(shipment, _ix) : const <String>[];\n    final allChecksConfirmed = _inspectionMissingNow.isEmpty;\n"],["          Text(t.detail.items.toUpperCase(), style: const TextStyle(fontSize: 11.5, fontWeight: FontWeight.w700, color: HubColors.muted)),","          Text((mode == _ItemsCardMode.interactive ? _ix.title : t.detail.items).toUpperCase(), style: const TextStyle(fontSize: 11.5, fontWeight: FontWeight.w700, color: HubColors.muted)),"],["          if (!allChecksConfirmed) ...[\n            const SizedBox(height: 8),\n            const Text('Confirm every checklist item above before marking as inspected.', style: TextStyle(fontSize: 11.5, color: HubColors.red)),\n          ],\n","          if (nextStatus == 'inspected') ...[\n            const SizedBox(height: 12),\n            _buildInspectionStatus(),\n          ],\n"]],"block":{"from":"  /// Confirmed with the person: the same spec set already shown, now\n","to":"  Widget _buildMainStepForm(","text":"  /// The inspection list (migration 129): the server builds it, so the hub portal shows exactly the same lines (part, OEM, position, specs, and\n  /// the condition line). The ticks are saved on the server as they are made, so work started here can be finished on the portal.\n  InspectionText get _ix => kInspectionText[Provider.of<LanguageState>(context, listen: false).language] ?? kInspectionText['en']!;\n\n  /// The received quantity as typed (or as saved), or null when it is empty or not a whole number.\n  int? _receivedNow(ShipmentItem item) {\n    final c = _receivedControllers[item.productId];\n    if (c == null) return item.receivedQuantity;\n    final v = int.tryParse(c.text.trim());\n    return (v == null || v < 0) ? null : v;\n  }\n\n  /// What still stops \"Confirm Inspected\", one line per problem (empty: it may go on). The server checks the same.\n  List<String> _inspectionMissing(ShipmentDetail shipment, InspectionText x) {\n    final out = <String>[];\n    for (final item in shipment.items) {\n      final checked = _checkedSpecs[item.productId] ?? item.checkedKeys.toSet();\n      final left = item.checklist.where((c) => !checked.contains(c.key)).length;\n      if (left > 0) out.add(x.needChecks(item.name, left));\n      final received = _receivedNow(item);\n      if (received == null) {\n        out.add(x.needQuantity(item.name));\n      } else if (received != item.quantity && shipment.resolution != 'continue_processing') {\n        out.add(x.needFlag(item.name, received, item.quantity));\n      }\n    }\n    return out;\n  }\n\n  Future<void> _saveChecks(String productId, Set<String> before) async {\n    final auth = context.read<AuthState>();\n    try {\n      await ApiClient().saveInspectionChecks(auth.token!, widget.shipmentId, productId, (_checkedSpecs[productId] ?? <String>{}).toList());\n    } on SessionExpiredError {\n      auth.handleSessionExpired();\n    } on ApiException catch (e) {\n      if (!mounted) return;\n      setState(() {\n        _checkedSpecs[productId] = before;      // not saved: the tick goes back, so what is shown is what the server has\n        _errorMessage = e.isNetworkError ? _ix.saveFailed : e.message;\n      });\n    }\n  }\n\n  void _setChecks(ShipmentItem item, Set<String> next) {\n    final before = {...(_checkedSpecs[item.productId] ?? <String>{})};\n    setState(() => _checkedSpecs[item.productId] = next);\n    _saveChecks(item.productId, before);\n  }\n\n  Widget _buildItemVerificationRow(ShipmentItem item, _ItemsCardMode mode) {\n    final x = _ix;\n    final lang = Provider.of<LanguageState>(context, listen: false).language;      // build already watches the language\n    final controller = _receivedControllers.putIfAbsent(\n      item.productId,\n      () => TextEditingController(text: item.receivedQuantity?.toString() ?? ''),\n    );\n    final received = mode == _ItemsCardMode.interactive ? _receivedNow(item) : item.receivedQuantity;\n    final hasMismatch = received != null && received != item.quantity;\n    final missingQuantity = mode == _ItemsCardMode.interactive && received == null;\n    final specs = item.checklist;\n    final checked = _checkedSpecs.putIfAbsent(item.productId, () => item.checkedKeys.toSet());\n    // the list itself shows only while inspecting; before it is hidden, after it the quantity is shown read-only\n    final showChecklist = mode == _ItemsCardMode.interactive;\n    final quantityColor = hasMismatch || missingQuantity ? HubColors.red : HubColors.gauge;\n    return Container(\n      margin: const EdgeInsets.only(bottom: 8),\n      padding: const EdgeInsets.all(10),\n      decoration: BoxDecoration(\n        color: hasMismatch ? HubColors.redBg : HubColors.card,\n        border: Border.all(color: hasMismatch ? HubColors.red : HubColors.line),\n        borderRadius: BorderRadius.circular(8),\n      ),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Text('${item.name} × ${item.quantity}', style: const TextStyle(fontSize: 13.5, fontWeight: FontWeight.w700, color: HubColors.ink)),\n          if (showChecklist && specs.isNotEmpty) ...[\n            const SizedBox(height: 6),\n            ...specs.map((c) {\n              final isChecked = checked.contains(c.key);\n              return InkWell(\n                key: Key('check-${item.productId}-${c.key}'),\n                onTap: () => _setChecks(item, isChecked ? ({...checked}..remove(c.key)) : ({...checked}..add(c.key))),\n                child: Padding(\n                  padding: const EdgeInsets.symmetric(vertical: 3),\n                  child: Row(\n                    children: [\n                      Icon(isChecked ? Icons.check_box : Icons.check_box_outline_blank, size: 18, color: isChecked ? HubColors.gauge : HubColors.muted),\n                      const SizedBox(width: 8),\n                      Expanded(child: Text(c.label(lang), style: TextStyle(fontSize: 12.5, color: isChecked ? HubColors.ink : HubColors.muted))),\n                    ],\n                  ),\n                ),\n              );\n            }),\n            const SizedBox(height: 2),\n            Row(\n              children: [\n                Text(x.checksDone(specs.where((c) => checked.contains(c.key)).length, specs.length), style: const TextStyle(fontSize: 10.5, color: HubColors.muted)),\n                const Spacer(),\n                if (specs.any((c) => !checked.contains(c.key)))\n                  InkWell(\n                    onTap: () => _setChecks(item, specs.map((c) => c.key).toSet()),\n                    child: Padding(\n                      padding: const EdgeInsets.symmetric(vertical: 3),\n                      child: Text(x.checkAll, style: const TextStyle(fontSize: 11.5, fontWeight: FontWeight.w600, color: HubColors.torque)),\n                    ),\n                  ),\n              ],\n            ),\n          ],\n          const SizedBox(height: 6),\n          Row(\n            children: [\n              Text('${x.ordered}: ${item.quantity}', style: const TextStyle(fontSize: 12, color: HubColors.muted)),\n              const Spacer(),\n              Text(\n                '${x.received}:',\n                style: TextStyle(fontSize: 12, fontWeight: hasMismatch ? FontWeight.w700 : FontWeight.w400, color: hasMismatch ? HubColors.red : HubColors.muted),\n              ),\n              const SizedBox(width: 6),\n              if (mode == _ItemsCardMode.readOnly)\n                Text(\n                  item.receivedQuantity?.toString() ?? '—',\n                  style: TextStyle(fontSize: 12.5, fontWeight: FontWeight.w700, color: hasMismatch ? HubColors.red : HubColors.ink),\n                )\n              else\n                SizedBox(\n                  width: 56,\n                  height: 34,\n                  child: TextField(\n                    key: Key('received-${item.productId}'),\n                    controller: controller,\n                    keyboardType: TextInputType.number,\n                    textAlign: TextAlign.center,\n                    style: TextStyle(fontSize: 13, fontWeight: FontWeight.w700, color: hasMismatch ? HubColors.red : HubColors.ink),\n                    decoration: InputDecoration(\n                      isDense: true,\n                      filled: missingQuantity,\n                      fillColor: HubColors.redBg,\n                      contentPadding: const EdgeInsets.symmetric(vertical: 6),\n                      enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(6), borderSide: BorderSide(color: quantityColor, width: 1.5)),\n                      focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(6), borderSide: BorderSide(color: quantityColor, width: 2)),\n                    ),\n                    onChanged: (_) => setState(() {}),      // the \"still needed\" list follows what is typed\n                    onSubmitted: (value) => _saveReceivedQuantity(item.productId, value),\n                    onEditingComplete: () => _saveReceivedQuantity(item.productId, controller.text),\n                  ),\n                ),\n            ],\n          ),\n          if (missingQuantity) ...[\n            const SizedBox(height: 6),\n            Text(x.enterQuantity, style: const TextStyle(fontSize: 11, fontWeight: FontWeight.w600, color: HubColors.red)),\n          ] else if (hasMismatch && mode == _ItemsCardMode.interactive && _shipment?.resolution != 'continue_processing') ...[\n            const SizedBox(height: 6),\n            Text(x.mismatchHint, style: const TextStyle(fontSize: 11, fontWeight: FontWeight.w600, color: HubColors.red)),\n          ],\n        ],\n      ),\n    );\n  }\n\n  /// Under the inspecting step's button: what is still missing (red), or that everything is confirmed (green).\n  Widget _buildInspectionStatus() {\n    final x = _ix;\n    if (_inspectionMissingNow.isEmpty) {\n      return Container(\n        width: double.infinity,\n        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),\n        decoration: BoxDecoration(color: HubColors.gaugeBg, borderRadius: BorderRadius.circular(10)),\n        child: Text('✓ ${x.allDone}', style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w700, color: HubColors.gauge)),\n      );\n    }\n    return Container(\n      key: const Key('inspection-missing'),\n      width: double.infinity,\n      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),\n      decoration: BoxDecoration(color: HubColors.redBg, borderRadius: BorderRadius.circular(10)),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Text(x.stillNeeded, style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w700, color: HubColors.red)),\n          const SizedBox(height: 4),\n          ..._inspectionMissingNow.map((line) => Text('• $line', style: const TextStyle(fontSize: 12, color: HubColors.red))),\n        ],\n      ),\n    );\n  }\n\n"}},{"file":"apps/admin-dashboard/src/hubFixtures.js","what":"tests: the hub test helper passes the inspection list","done":"export async function passInspection","pairs":[["    if (step === 'shipped_to_buyer') await clearParcelCost(shipment.id, { login, hubToken: token });","    if (step === 'inspected') await passInspection(shipment.id, { login, hubToken: token });      // the inspection list (migration 129)\n    if (step === 'shipped_to_buyer') await clearParcelCost(shipment.id, { login, hubToken: token });"],["export async function clearParcelCost(","/**\n * Test helper: the inspection list (migration 129) for an OPENED shipment, so it may then be marked inspected: every line of every item ticked,\n * and each item's received quantity entered (equal to the order). Call it before posting the \"inspected\" step in a test that does it itself.\n */\nexport async function passInspection(shipmentId, { login, hubToken }) {\n  const token = hubToken || (await login('hub@leap.dev', 'hub_dev_password_123')).token;\n  const headers = { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` };\n  const detail = await fetch(`${BACKEND_URL}/hub/me/shipments/${shipmentId}`, { headers }).then((r) => r.json());\n  for (const item of detail.items || []) {\n    for (const [method, part, body] of [['PUT', 'checks', { checked: (item.checklist || []).map((c) => c.key) }], ['PATCH', 'received', { receivedQuantity: item.quantity }]]) {\n      const res = await fetch(`${BACKEND_URL}/hub/me/shipments/${shipmentId}/items/${encodeURIComponent(item.productId)}/${part}`, { method, headers, body: JSON.stringify(body) });\n      if (res.status !== 200) throw new Error(`Inspection list (${part}) failed (${res.status}): ${JSON.stringify(await res.json())}`);\n    }\n  }\n}\n\nexport async function clearParcelCost("]],"optional":true},{"file":"apps/hub-portal/src/hubPortal.integration.test.js","what":"tests: the hub portal's end-to-end test passes the inspection list","done":"the inspection list (migration 129)","pairs":[["      const photo = await uploadRealPhoto(hubToken);\n      const result = await recordShipmentEvent(hubToken, shipment.id, { step, notes: `${step} — real note`, photos: [photo.url] });","      if (step === 'inspected') {      // the inspection list (migration 129): every line ticked, every item's received quantity entered\n        const detail = await fetchMyShipmentById(hubToken, shipment.id);\n        const headers = { 'Content-Type': 'application/json', Authorization: `Bearer ${hubToken}` };\n        for (const item of detail.items) {\n          await fetch(`${BACKEND_URL}/hub/me/shipments/${shipment.id}/items/${encodeURIComponent(item.productId)}/checks`, { method: 'PUT', headers, body: JSON.stringify({ checked: item.checklist.map((c) => c.key) }) });\n          await fetch(`${BACKEND_URL}/hub/me/shipments/${shipment.id}/items/${encodeURIComponent(item.productId)}/received`, { method: 'PATCH', headers, body: JSON.stringify({ receivedQuantity: item.quantity }) });\n        }\n      }\n      const photo = await uploadRealPhoto(hubToken);\n      const result = await recordShipmentEvent(hubToken, shipment.id, { step, notes: `${step} — real note`, photos: [photo.url] });"]],"optional":true}]};
const plan = [];
let problems = 0;
const once = (s, a) => s.split(a).length === 2;
const read = (file) => { const p = path.join(root, file); return fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : null; };
function edit(file, what, done, change) {
  const s = read(file);
  if (s === null) { console.log(`MISSING   ${file}: not found. Run this from D:\\LEAP-MARKETPLACE.`); problems++; return; }
  if (s.replace(/\r\n/g, '\n').includes(done)) { console.log(`already   ${file}: ${what}`); return; }
  const eol = s.includes('\r\n') ? '\r\n' : '\n';
  const out = change(s.replace(/\r\n/g, '\n'));
  if (typeof out !== 'string') { console.log(`REFUSED   ${file}: ${out && out.why ? out.why : 'its text is not what this patch expects'}, so nothing was changed. Send this file.`); problems++; return; }
  plan.push({ file, what, before: s, after: out.replace(/\n/g, eol) });
}

for (const e of DATA.created) {
  const p = path.join(root, e.file);
  if (fs.existsSync(p)) {
    if (fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n') === e.text) { console.log(`already   ${e.file}: ${e.what}`); continue; }
    console.log(`REFUSED   ${e.file}: a different file with this name is already there, so nothing was changed. Send this file.`); problems++; continue;
  }
  // a new folder (services/api/src/modules/inspection) is made, but only inside one that is already there
  if (!fs.existsSync(path.dirname(path.dirname(p)))) { console.log(`MISSING   ${path.dirname(path.dirname(e.file))}: folder not found. Run this from D:\\LEAP-MARKETPLACE.`); problems++; continue; }
  plan.push({ file: e.file, what: e.what, before: null, after: e.text });
}
for (const e of DATA.anchored) {
  // a test file: changed when it is there and as expected, otherwise left as it is (it does not stop the patch)
  if (e.optional) {
    const s = read(e.file);
    if (s === null) { console.log(`skipped   ${e.file}: not found (a test file; nothing to do)`); continue; }
    const n = s.replace(/\r\n/g, '\n');
    if (!n.includes(e.done) && e.pairs.some(([a]) => !once(n, a))) { console.log(`skipped   ${e.file}: not as expected, left as it is (${e.what})`); continue; }
  }
  edit(e.file, e.what, e.done, (s) => {
    let out = s;
    for (const [a, b] of e.pairs) { if (!once(out, a)) return { why: `this part was not found: "${a.split('\n').find((l) => l.trim()).trim().slice(0, 90)}"` }; out = out.replace(a, () => b); }
    if (e.block) {
      const i = out.indexOf(e.block.from); const j = i < 0 ? -1 : out.indexOf(e.block.to, i);
      if (i < 0 || j < 0) return { why: 'the item checklist code (_specLabelsFor ... _buildMainStepForm) was not found' };
      out = out.slice(0, i) + e.block.text + out.slice(j);
    }
    return out;
  });
}
if (problems > 0) { console.log('\nNothing was changed, because of the problem(s) above.'); process.exit(1); }
for (const c of plan) {
  if (write) {
    const p = path.join(root, c.file);
    if (c.before !== null) fs.writeFileSync(`${p}.before-inspection-list`, c.before);
    fs.mkdirSync(path.dirname(p), { recursive: true });
    fs.writeFileSync(p, c.after);
    console.log(`${c.before === null ? 'created ' : 'patched '}  ${c.file}: ${c.what}`);
  } else console.log(`would     ${c.file}: ${c.what}`);
}
if (!write && plan.length) console.log('\nDry run only. Add --write to apply.');
if (write && plan.length) console.log('\nDone. Then: cd services\\api ; npm run migrate ; restart the API. Hub portal: Ctrl+F5. Hub app: q, then flutter run with your API address.');
